import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第三册：培养技能 · 全册易错点 · 第45–60课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第三册：培养技能 · 全册易错点 · 第45–60课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-3/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册易错点 · 第22–44课","link":"/life/english/new-concept/book-3/mistakes-part-02"},"next":{"text":"第三册：培养技能 · 综合复习与自测","link":"/life/english/new-concept/book-3/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册易错点 · 第22–44课","link":"/life/english/new-concept/book-3/mistakes-part-02"},"next":{"text":"第三册：培养技能 · 综合复习与自测","link":"/life/english/new-concept/book-3/review"}},"headers":[],"relativePath":"life/english/new-concept/book-3/mistakes-part-03.md","filePath":"life/english/new-concept/book-3/mistakes-part-03.md"}'),r={name:"life/english/new-concept/book-3/mistakes-part-03.md"};function i(l,e,s,h,p,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-全册易错点-·-第45–60课" tabindex="-1">第三册：培养技能 · 全册易错点 · 第45–60课 <a class="header-anchor" href="#第三册-培养技能-·-全册易错点-·-第45–60课" aria-label="Permalink to &quot;第三册：培养技能 · 全册易错点 · 第45–60课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="l45-·-报告动词及其结构" tabindex="-1">L45 · 报告动词及其结构 <a class="header-anchor" href="#l45-·-报告动词及其结构" aria-label="Permalink to &quot;L45 · 报告动词及其结构 {#l45-·-报告动词及其结构}&quot;">​</a></h2><p>She suggested me to write 错误；可写 She suggested that I write 或 She suggested writing，视执行者是否需要明确。</p><p><strong>对照例句：</strong> The reporter stated the figures, while the campaigner claimed that they showed a wider problem.</p><p>stated 与 claimed 区分陈述和观点；they 回指 figures，后半结论归属于 campaigner。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-045">回看讲解和练习</a></p><h2 id="l46-·-过去能力与一次成功" tabindex="-1">L46 · 过去能力与一次成功 <a class="header-anchor" href="#l46-·-过去能力与一次成功" aria-label="Permalink to &quot;L46 · 过去能力与一次成功 {#l46-·-过去能力与一次成功}&quot;">​</a></h2><p>I tried to fix it 不表示已经修好；若要确认成功，可写 I managed to fix it。</p><p><strong>对照例句：</strong> After several careful attempts, I managed to remove the damaged screw.</p><p>managed to remove 表示实际成功，after 短语解释此前有困难和尝试。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-046">回看讲解和练习</a></p><h2 id="l47-·-because、therefore-与因果关系" tabindex="-1">L47 · because、therefore 与因果关系 <a class="header-anchor" href="#l47-·-because、therefore-与因果关系" aria-label="Permalink to &quot;L47 · because、therefore 与因果关系 {#l47-·-because、therefore-与因果关系}&quot;">​</a></h2><p>Because of the traffic was loud 错把完整句接在介词后；可写 Because the traffic was loud 或 Because of the loud traffic。</p><p><strong>对照例句：</strong> The courtyard remained noisy after midnight; therefore, several residents moved their bedrooms to the rear.</p><p>分号分开完整分句，therefore 标明结果；several 限定受影响者，未概括为所有住户。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">回看讲解和练习</a></p><h2 id="l48-·-地点前置的完全倒装" tabindex="-1">L48 · 地点前置的完全倒装 <a class="header-anchor" href="#l48-·-地点前置的完全倒装" aria-label="Permalink to &quot;L48 · 地点前置的完全倒装 {#l48-·-地点前置的完全倒装}&quot;">​</a></h2><p>Here comes it 应为 Here it comes；代词主语通常不按名词主语的方式后置。</p><p><strong>对照例句：</strong> Beyond the empty square stood a row of houses with closed shutters.</p><p>地点短语前置，stood 在名词主语 a row of houses 之前，构成完全倒装。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-048">回看讲解和练习</a></p><h2 id="l49-·-介词加关系代词" tabindex="-1">L49 · 介词加关系代词 <a class="header-anchor" href="#l49-·-介词加关系代词" aria-label="Permalink to &quot;L49 · 介词加关系代词 {#l49-·-介词加关系代词}&quot;">​</a></h2><p>the person on that we rely 不成立，介词前置需用 whom；或写 the person that we rely on。</p><p><strong>对照例句：</strong> The assistant on whom the household relied kept a careful record of every delivery.</p><p>on whom 引导限定从句，on 来自 rely on；从句修饰 assistant。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-049">回看讲解和练习</a></p><h2 id="l50-·-动词后-ing-与-to-do-的意义" tabindex="-1">L50 · 动词后 ing 与 to do 的意义 <a class="header-anchor" href="#l50-·-动词后-ing-与-to-do-的意义" aria-label="Permalink to &quot;L50 · 动词后 ing 与 to do 的意义 {#l50-·-动词后-ing-与-to-do-的意义}&quot;">​</a></h2><p>I stopped to smoke 表示停下其他事去抽烟，不能用来表达戒烟；戒烟应是 stopped smoking。</p><p><strong>对照例句：</strong> I stopped checking messages during study sessions and tried leaving my phone in another room.</p><p>stopped checking 是终止行为；tried leaving 是试用一个办法，而非宣称最终一定成功。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-050">回看讲解和练习</a></p><h2 id="l51-·-将来完成时的截止视角" tabindex="-1">L51 · 将来完成时的截止视角 <a class="header-anchor" href="#l51-·-将来完成时的截止视角" aria-label="Permalink to &quot;L51 · 将来完成时的截止视角 {#l51-·-将来完成时的截止视角}&quot;">​</a></h2><p>By the time she will arrive 不符合普通未来时间从句用法，应写 By the time she arrives。</p><p><strong>对照例句：</strong> If the schedule holds, the team will have tested all three models by Friday.</p><p>will have tested 以 Friday 为截止参照；if 从句使结果明确依赖进度条件。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-051">回看讲解和练习</a></p><h2 id="l52-·-名词化与动作还原" tabindex="-1">L52 · 名词化与动作还原 <a class="header-anchor" href="#l52-·-名词化与动作还原" aria-label="Permalink to &quot;L52 · 名词化与动作还原 {#l52-·-名词化与动作还原}&quot;">​</a></h2><p>把抽象被动改主动时不能凭空加入专家等未提供的行动者；未知主体可保留被动或明确写“报告未说明”。</p><p><strong>对照例句：</strong> The seller called the mixture a premium finish, but the label did not explain its ingredients.</p><p>called 加宾语和名词补语报告命名；but 后用具体缺失信息检验宣传，而非仅凭名称判断品质。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-052">回看讲解和练习</a></p><h2 id="l53-·-形式主语与真正主语" tabindex="-1">L53 · 形式主语与真正主语 <a class="header-anchor" href="#l53-·-形式主语与真正主语" aria-label="Permalink to &quot;L53 · 形式主语与真正主语 {#l53-·-形式主语与真正主语}&quot;">​</a></h2><p>It is kind for you to help 在评价人的善意时通常用 of you；说明任务对某人重要则用 important for you to ...。</p><p><strong>对照例句：</strong> It is essential that every complaint be recorded before the review begins.</p><p>it 为形式主语；that 从句为真正评价对象；be recorded 使用建议性原形虚拟式被动。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-053">回看讲解和练习</a></p><h2 id="l54-·-whatever-与-no-matter-what" tabindex="-1">L54 · whatever 与 no matter what <a class="header-anchor" href="#l54-·-whatever-与-no-matter-what" aria-label="Permalink to &quot;L54 · whatever 与 no matter what {#l54-·-whatever-与-no-matter-what}&quot;">​</a></h2><p>Take no matter what you need 不符合标准宾语结构，应写 Take whatever you need；no matter what 不能普遍替代 whatever。</p><p><strong>对照例句：</strong> Whatever caused the bird to choose the red lid, one trial cannot establish a general rule.</p><p>whatever 从句作让步状语；主句独立成立，强调证据数量的限制。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-054">回看讲解和练习</a></p><h2 id="l55-·-省略-if-的条件倒装" tabindex="-1">L55 · 省略 if 的条件倒装 <a class="header-anchor" href="#l55-·-省略-if-的条件倒装" aria-label="Permalink to &quot;L55 · 省略 if 的条件倒装 {#l55-·-省略-if-的条件倒装}&quot;">​</a></h2><p>If they received 不能直接变为 Received they；只有符合条件的 had、were、should 等可用于此类倒装。</p><p><strong>对照例句：</strong> Should anyone detect the signal, the repeated pattern may help them recognize it as intentional.</p><p>Should anyone detect 等于 If anyone should detect；may 保留识别成功的不确定性。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-055">回看讲解和练习</a></p><h2 id="l56-·-混合时间条件句" tabindex="-1">L56 · 混合时间条件句 <a class="header-anchor" href="#l56-·-混合时间条件句" aria-label="Permalink to &quot;L56 · 混合时间条件句 {#l56-·-混合时间条件句}&quot;">​</a></h2><p>would have been dry now 通常不如 would be dry now 清楚，因为这里明确评价现在状态，而非过去已经完成的结果。</p><p><strong>对照例句：</strong> If we had moved the supplies upstairs yesterday, they would be dry now.</p><p>had moved 指昨日未做的动作，would be dry now 表示当前反事实状态。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-056">回看讲解和练习</a></p><h2 id="l57-·-as-if-与假设语气" tabindex="-1">L57 · as if 与假设语气 <a class="header-anchor" href="#l57-·-as-if-与假设语气" aria-label="Permalink to &quot;L57 · as if 与假设语气 {#l57-·-as-if-与假设语气}&quot;">​</a></h2><p>as if 并不自动证明 nothing had changed；它可只描述气味带来的感受，其他方面仍可能变化。</p><p><strong>对照例句：</strong> The bakery smelled as if nothing had changed since my childhood.</p><p>as if 引出主观印象；had changed 以过去 smelled 为参照，since 标明持续范围。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-057">回看讲解和练习</a></p><h2 id="l58-·-but-for-与-without-的隐含条件" tabindex="-1">L58 · but for 与 without 的隐含条件 <a class="header-anchor" href="#l58-·-but-for-与-without-的隐含条件" aria-label="Permalink to &quot;L58 · but for 与 without 的隐含条件 {#l58-·-but-for-与-without-的隐含条件}&quot;">​</a></h2><p>But for she helped us 结构不成立，应写 But for her help，或 If she had not helped us。</p><p><strong>对照例句：</strong> But for the dated receipt, we would have been unable to explain the mix-up.</p><p>but for 引出过去反事实条件，would have been unable 描述过去本可能出现的结果。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-058">回看讲解和练习</a></p><h2 id="l59-·-动名词作主语与宾语" tabindex="-1">L59 · 动名词作主语与宾语 <a class="header-anchor" href="#l59-·-动名词作主语与宾语" aria-label="Permalink to &quot;L59 · 动名词作主语与宾语 {#l59-·-动名词作主语与宾语}&quot;">​</a></h2><p>Collecting maps have taught me 错把 maps 当作主语中心；真正主语是收藏活动，通常用 has。</p><p><strong>对照例句：</strong> Collecting old maps has taught me to notice how place names change.</p><p>Collecting old maps 整体作单数主语，谓语为 has taught；how 从句为 notice 的宾语。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-059">回看讲解和练习</a></p><h2 id="l60-·-时间从句与将来表达整合" tabindex="-1">L60 · 时间从句与将来表达整合 <a class="header-anchor" href="#l60-·-时间从句与将来表达整合" aria-label="Permalink to &quot;L60 · 时间从句与将来表达整合 {#l60-·-时间从句与将来表达整合}&quot;">​</a></h2><p>I don&#39;t know when he arrives tomorrow 与 when he will arrive tomorrow 可依语境不同；间接疑问并不受“时间从句不能用 will”的简单规则限制。</p><p><strong>对照例句：</strong> Please call me when you arrive, and I will meet you at the side entrance.</p><p>when you arrive 是未来时间从句，用现在时；主句后半用 will 表示响应行动。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-060">回看讲解和练习</a></p>',83)])])}const u=a(r,[["render",i]]);export{f as __pageData,u as default};
